node --input-type=module -e 'import fs from '\''node:fs'\'';import {validateTracker,sha256} from '\''./scripts/remediation/board.mjs'\'';
const priorRaw=fs.readFileSync('\''docs/remediation/evidence/W05.01/tracker-before-v1.json'\'');
const priorHash=sha256(priorRaw);
if(priorHash!=='\''230c8e4e18e10d11aa8c8019782cd502966125994051c65866b8b4bfbbdb2510'\'')throw new Error('\''trusted207 raw hash mismatch'\'');
const tracker=JSON.parse(fs.readFileSync('\''docs/remediation/tracker.json'\'','\''utf8'\''));
const result=validateTracker(tracker,{rootDir:process.cwd(),previousTracker:JSON.parse(priorRaw)});
console.log(JSON.stringify({at:new Date().toISOString(),journal_seq:tracker.journal.length,trusted_prior_seq:207,trusted_prior_sha256:priorHash,result}));
