pre_full_check_sanity.command:
import fs from 'node:fs';import {sha256,taskContractDigest,artifactDigest} from './scripts/remediation/board.mjs';
const t=JSON.parse(fs.readFileSync('docs/remediation/tracker.json','utf8')),p=JSON.parse(fs.readFileSync('docs/remediation/evidence/W05.01/tracker-before-v1.json','utf8'));const errors=[];
if(JSON.stringify(t.journal.slice(0,p.journal.length))!==JSON.stringify(p.journal))errors.push('prefix');
for(const e of t.journal.slice(p.journal.length).filter(e=>e.kind==='record_change')){const bytes=fs.readFileSync(e.record.path),r=JSON.parse(bytes);if(sha256(bytes)!==e.record.sha256||(r.before===null?null:sha256(JSON.stringify(r.before)))!==e.before_sha256||sha256(JSON.stringify(r.after))!==e.after_sha256)errors.push('record:'+e.seq);}
const task=t.tasks.find(x=>x.id==='W05.01');
if(taskContractDigest(task)!==task.preflight.contract_digest||artifactDigest(task.artifact)!==task.artifact.digest||sha256(JSON.stringify(task.independent_review))!==task.lead_signoff.review_sha256)errors.push('taskdigests');
if(t.journal.length!==221||task.state!=='closed'||t.resume.journal_seq!==221)errors.push('state');
console.log(JSON.stringify({at:new Date().toISOString(),seq:t.journal.length,errors}));if(errors.length)process.exitCode=1;
